    last_def = {"left": param_def_line, "right": param_def_line}

    def tracer(frame, event, arg):
        if frame.f_code is multiply.__code__:
            if event == 'call':
                frame.f_trace_opcodes = True
                return tracer
            if event == 'opcode':
