                if var in TRACK:
                    if op in ('LOAD_FAST',):
                        if var in last_def:
                            pairs.add((var, last_def[var], line))
                    elif op in ('STORE_FAST',):
                        last_def[var] = line
        return tracer

    old = sys.gettrace()
    sys.settrace(tracer)
    try:
        res = pybamm.multiply(base, right)
    finally:
        sys.settrace(old)
    assert res is numerator
    return pairs

for param_line in (1100,1101,1102):
    per = [run_seed(i,param_line) for i in range(1,11)]
    inter = set.intersection(*per)
